From 7bb55ed099f611ec7077db69684a6cb93d42dc70 Mon Sep 17 00:00:00 2001
From: Yu Watanabe <watanabe.yu+github@gmail.com>
Date: Sun, 24 Mar 2019 00:22:38 +0900
Subject: [PATCH] util: fix condition_free_list_type()

This fixes a bug introduced by c4f58deab56282cd438922203287cb073b861513.

Closes oss-fuzz#13878, oss-fuzz#13882, oss-fuzz#13884, oss-fuzz#13886, and
oss-fuzz#13888.

diff --git a/src/shared/condition.c b/src/shared/condition.c
index 69d65fffbc..32a90bcea3 100644
--- a/src/shared/condition.c
+++ b/src/shared/condition.c
@@ -77,17 +77,17 @@ void condition_free(Condition *c) {
         free(c);
 }

-Condition* condition_free_list_type(Condition *first, ConditionType type) {
-        Condition *c, *n, *r = NULL;
+Condition* condition_free_list_type(Condition *head, ConditionType type) {
+        Condition *c, *n;

-        LIST_FOREACH_SAFE(conditions, c, n, first)
-                if (type < 0 || c->type == type)
+        LIST_FOREACH_SAFE(conditions, c, n, head)
+                if (type < 0 || c->type == type) {
+                        LIST_REMOVE(conditions, head, c);
                         condition_free(c);
-                else if (!r)
-                        r = c;
+                }

-        assert(type >= 0 || !r);
-        return r;
+        assert(type >= 0 || !head);
+        return head;
 }

 static int condition_test_kernel_command_line(Condition *c) {
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the incorrect handling of the linked list of conditions in the `condition_free_list_type` function. Specifically, the function did not properly remove conditions from the list when they were freed, which could lead to memory leaks or accessing freed memory. The original implementation used an incorrect variable for list traversal and removal, which resulted in conditions not being removed as intended.

        Commit message:
        util: fix condition_free_list_type()

This fixes a bug introduced by c4f58deab56282cd438922203287cb073b861513.

Closes oss-fuzz#13878, oss-fuzz#13882, oss-fuzz#13884, oss-fuzz#13886, and
oss-fuzz#13888.  

        Patch:

-Condition* condition_free_list_type(Condition *first, ConditionType type) {
-        Condition *c, *n, *r = NULL;
+Condition* condition_free_list_type(Condition *head, ConditionType type) {
+        Condition *c, *n;

-        LIST_FOREACH_SAFE(conditions, c, n, first)
-                if (type < 0 || c->type == type)
+        LIST_FOREACH_SAFE(conditions, c, n, head)
+                if (type < 0 || c->type == type) {
+                        LIST_REMOVE(conditions, head, c);
                         condition_free(c);
-                else if (!r)
-                        r = c;
+                }

-        assert(type >= 0 || !r);
-        return r;
+        assert(type >= 0 || !head);
+        return head;
 }



        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
        ...
        <textN>

Code statements:
- LIST_FOREACH_SAFE(conditions, c, n, first)
+ LIST_FOREACH_SAFE(conditions, c, n, head)
+ LIST_REMOVE(conditions, head, c);
- assert(type >= 0 || !r);
+ assert(type >= 0 || !head);

Code statements:
- LIST_FOREACH_SAFE(conditions, c, n, first)
+ LIST_FOREACH_SAFE(conditions, c, n, head)
+ LIST_REMOVE(conditions, head, c);
- assert(type >= 0 || !r);
+ assert(type >= 0 || !head);
